package com.rumitx.app.tak;
import android.app.*;import android.os.*;import android.widget.*;import com.rumitx.app.*;import java.util.concurrent.*;
/** Native DMR007 messaging; never labels a module ACK as recipient delivery. */
public final class MessagingStatusActivity extends Activity {
 private EditText peer,body;private String threadPeer;private android.location.LocationManager gps;private android.location.LocationListener gpsListener;private TextView history,status;private Button send;private volatile boolean destroyed;private final Handler ui=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final Runnable refresh=new Runnable(){public void run(){if(destroyed)return;try(MessageStore store=new MessageStore(MessagingStatusActivity.this)){history.setText(store.history(threadPeer));getSharedPreferences("message_state",0).edit().putInt("unread",0).apply();}ui.postDelayed(this,1500);}};
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(0xffb5dae6);return v;}
 protected void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(10),dp(12),dp(10));root.setBackgroundColor(0xff050508);root.addView(label("RADIO MESSAGES",22));root.addView(label("Messages use your selected digital channel. The radio keeps listening in the background. Module acceptance is shown after sending; recipient delivery remains unconfirmed.",12));
 peer=new EditText(this);peer.setHint("Recipient DMR ID");peer.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);peer.setSingleLine(true);peer.setText(getSharedPreferences("message_state",0).getString("last_peer",""));root.addView(peer);body=new EditText(this);body.setHint("Message (120 characters maximum)");body.setMinLines(2);body.setMaxLines(3);body.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(120)});root.addView(body);LinearLayout tools=new LinearLayout(this);tools.setOrientation(0);Button dictate=new Button(this);dictate.setText("DICTATE");dictate.setTextSize(10);dictate.setOnClickListener(v->dictate());tools.addView(dictate,new LinearLayout.LayoutParams(0,dp(48),1));Button preset=new Button(this);preset.setText("PRESETS");preset.setTextSize(10);preset.setOnClickListener(v->presets());tools.addView(preset,new LinearLayout.LayoutParams(0,dp(48),1));Button location=new Button(this);location.setText("GPS TEXT");location.setTextSize(10);location.setOnClickListener(v->location());tools.addView(location,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(tools);send=new Button(this);send.setText("SEND DMR TEXT");root.addView(send);status=label("Select a digital channel before sending.",12);root.addView(status);
 send.setOnClickListener(v->{String id=peer.getText().toString().trim(),text=body.getText().toString().trim();try{long n=Long.parseLong(id);if(n<1||n>16777215||text.isEmpty())throw new IllegalArgumentException();}catch(Exception e){status.setText("Enter a recipient ID from 1 to 16777215 and a message.");return;}new AlertDialog.Builder(this).setTitle("Send radio text?").setMessage("Transmit this text to DMR ID "+id+" on the selected channel?").setNegativeButton("CANCEL",null).setPositiveButton("SEND",(d,w)->transmit(id,text)).show();});
 Button bridge=new Button(this);bridge.setText("GEOCHAT BRIDGE");bridge.setOnClickListener(v->bridge());root.addView(bridge);Spinner conversations=new Spinner(this);conversations.setMinimumHeight(dp(40));java.util.List<String> choices=new java.util.ArrayList<>();choices.add("ALL MESSAGES");try(MessageStore store=new MessageStore(this)){choices.addAll(store.peers());}conversations.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,choices));conversations.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){threadPeer=n==0?null:choices.get(n);if(threadPeer!=null)peer.setText(threadPeer);}});root.addView(conversations);root.addView(label("MESSAGE HISTORY",13));history=label("",14);history.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(history);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));Button back=new Button(this);back.setText("BACK TO RADIO");back.setOnClickListener(v->finish());root.addView(back);setContentView(root);}
 private void transmit(String id,String text){getSharedPreferences("message_state",0).edit().putString("last_peer",id).apply();send.setEnabled(false);status.setText("Sending…");worker.execute(()->{long row;try(MessageStore store=new MessageStore(this)){row=store.add(id,text,"out","Sending");String result;try{result=RadioController.getInstance().sendSms(id,text)?"Module accepted · delivery unconfirmed":"No module acknowledgement · delivery unknown";}catch(Exception e){result="Failed: "+e.getMessage();}store.status(row,result);final String outcome=result;ui.post(()->{if(destroyed)return;send.setEnabled(true);status.setText(outcome);if(outcome.startsWith("Module accepted"))body.setText("");});}catch(Exception e){ui.post(()->{if(!destroyed){send.setEnabled(true);status.setText("Could not save message: "+e.getMessage());}});}});}
 private void dictate(){try{android.content.Intent i=new android.content.Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(android.speech.RecognizerIntent.EXTRA_PROMPT,"Dictate radio text");startActivityForResult(i,244);}catch(android.content.ActivityNotFoundException e){status.setText("No speech recognition app installed · type your message");}}
 protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==244&&result==RESULT_OK&&data!=null){java.util.ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty())body.setText(words.get(0));}}
 private String[] presetValues(){return getSharedPreferences("message_presets",0).getString("values","On my way\nNeed backup\nArrived safely\nCall me on the radio").split("\n");}
 private void presets(){String[] values=presetValues();new AlertDialog.Builder(this).setTitle("Quick message").setItems(values,(d,n)->body.setText(values[n])).setNeutralButton("EDIT PRESETS",(d,n)->{EditText input=new EditText(this);input.setText(android.text.TextUtils.join("\n",values));input.setMinLines(4);new AlertDialog.Builder(this).setTitle("One preset per line").setView(input).setNegativeButton("CANCEL",null).setPositiveButton("SAVE",(dialog,w)->{String value=input.getText().toString().trim();if(!value.isEmpty()&&value.length()<=2000)getSharedPreferences("message_presets",0).edit().putString("values",value).apply();}).show();}).setNegativeButton("CANCEL",null).show();}
 private void location(){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){new AlertDialog.Builder(this).setTitle("GPS message").setMessage("Add your current coordinates to the draft. Coordinates are transmitted only when you press SEND.").setNegativeButton("CANCEL",null).setPositiveButton("CONTINUE",(d,w)->requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION},245)).show();return;}gps=(android.location.LocationManager)getSystemService(LOCATION_SERVICE);status.setText("Finding current GPS coordinates…");try{android.location.Location cached=gps.getLastKnownLocation(android.location.LocationManager.GPS_PROVIDER);if(fresh(cached)){coordinates(cached);return;}gpsListener=new android.location.LocationListener(){public void onLocationChanged(android.location.Location l){if(fresh(l)){coordinates(l);cancelGps();}}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};gps.requestLocationUpdates(android.location.LocationManager.GPS_PROVIDER,1000,0,gpsListener);ui.postDelayed(()->{if(gpsListener!=null){cancelGps();status.setText("No fresh GPS fix · move outdoors and try again");}},20000);}catch(Exception e){cancelGps();status.setText("GPS unavailable: "+e.getMessage());}}
 private boolean fresh(android.location.Location l){return l!=null&&android.os.SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos()>=0&&android.os.SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos()<120000000000L;}
 private void coordinates(android.location.Location l){body.setText(String.format(java.util.Locale.US,"Need assistance. GPS %.6f, %.6f",l.getLatitude(),l.getLongitude()));status.setText("Coordinates added to draft · review the recipient before sending");}
 private void cancelGps(){if(gps!=null&&gpsListener!=null)try{gps.removeUpdates(gpsListener);}catch(SecurityException ignored){}gpsListener=null;}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==245&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)location();}
 private void bridge(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);TextView info=label("With position sharing enabled, incoming radio texts are broadcast to ATAK GeoChat. GeoChat messages in the RumiTX Radio room, or addressed to this RumiTX UID, transmit to the DMR ID below. Other rooms are ignored.\nUID: "+TakSettings.uid(this)+"\n"+TakSettings.prefs(this).getString("bridge_status","Bridge off"),13);form.addView(info);EditText destination=new EditText(this);destination.setHint("DMR recipient ID for GeoChat → radio");destination.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);destination.setText(TakSettings.prefs(this).getString("bridge_peer",""));form.addView(destination);new AlertDialog.Builder(this).setTitle("GeoChat radio bridge").setView(form).setNegativeButton("OFF",(d,w)->{TakSettings.set(this,"geochat",false);GeoChatService.refresh(this);}).setNeutralButton("CANCEL",null).setPositiveButton("ENABLE",(d,w)->{String value=destination.getText().toString().trim();try{long n=Long.parseLong(value);if(n<1||n>16777215)throw new IllegalArgumentException();}catch(Exception e){status.setText("Enter a valid DMR destination ID");return;}TakSettings.prefs(this).edit().putString("bridge_peer",value).putBoolean("geochat",true).apply();GeoChatService.refresh(this);status.setText(TakSettings.enabled(this,"pli")?"GeoChat enabled · use room RumiTX Radio":"Bridge saved · enable position sharing in TAK settings to activate");}).show();}
 protected void onResume(){super.onResume();ui.post(refresh);}protected void onPause(){ui.removeCallbacks(refresh);cancelGps();super.onPause();}protected void onDestroy(){destroyed=true;ui.removeCallbacksAndMessages(null);worker.shutdown();super.onDestroy();}
}
